import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync, mkdirSync, statSync } from 'node:fs';

/**
 * The complete AI session used for the product quality review.
 *
 * Same converter as `packages/pipeline/src/jobs/export-ai-session.ts` (deliverable
 * 9), pointed at the review session and its own start boundary, and writing to a
 * separate directory. The repository's own script is not modified, because the
 * submission is not to be changed.
