/** Merge the session files, drop the duplicated handover records, restore order. */
const seen = new Set<string>();
const merged: Array<{ at: string; seq: number; line: string }> = [];
let duplicates = 0;
let seq = 0;
for (const file of SESSIONS) {
  for (const line of readFileSync(file, 'utf8').split('\n')) {
    if (!line.trim()) continue;
    let uuid = '';
    try { uuid = String(JSON.parse(line).uuid ?? ''); } catch { /* keep unparseable lines */ }
    if (uuid) {
      if (seen.has(uuid)) { duplicates++; continue; }
      seen.add(uuid);
    }
    let at = '';
    try { at = String(JSON.parse(line).timestamp ?? ''); } catch { /* no timestamp */ }
    merged.push({ at, seq: seq++, line });
  }
}
// Stable sort by timestamp; records without one keep their position relative to
// the file they came from rather than being bunched at the start.
merged.sort((a, b) => (a.at && b.at ? a.at.localeCompare(b.at) : 0) || a.seq - b.seq);
const lines = merged.map((m) => m.line);

